-- KV (Kauffrau/Kaufmann EFZ): Bildungsplan-Fragenkatalog (16 × 30 Fragen).
-- Idempotent, additiv und ohne Datenverlust:
--   * course_key-CHECK-Constraints werden auf
--     abu/automechaniker/fage/kv/schreiner/strassenbau erweitert.
--   * Module werden nach (course_key, title) gesucht oder angelegt.
--   * Lektionen werden nach (module_id, title) gesucht oder angelegt;
--     position/pass_score werden gesetzt.
--   * Fragen werden positionsbasiert UPSERTet: vorhandene (lesson_id,
--     position) werden aktualisiert (question.id bleibt erhalten, FKs zu
--     question_xp_awards / battle_answers bleiben intakt). Fehlende
--     Positionen werden eingefügt. Positionen > 30 werden entfernt.
--   * Profile, lesson_progress, lesson_attempts werden nicht angetastet.

begin;

-- ============================================================
-- 1) course_key-CHECK-Constraints erweitern
-- ============================================================
do $$
begin
  if exists (select 1 from pg_constraint where conname = 'profiles_active_course_key_ck') then
    alter table public.profiles drop constraint profiles_active_course_key_ck;
  end if;
  alter table public.profiles
    add constraint profiles_active_course_key_ck check (active_course_key in ('abu', 'automechaniker', 'fage', 'kv', 'schreiner', 'strassenbau'));
end$$;

do $$
begin
  if exists (select 1 from pg_constraint where conname = 'modules_course_key_ck') then
    alter table public.modules drop constraint modules_course_key_ck;
  end if;
  alter table public.modules
    add constraint modules_course_key_ck check (course_key in ('abu', 'automechaniker', 'fage', 'kv', 'schreiner', 'strassenbau'));
end$$;

do $$
begin
  if to_regclass('public.battle_matches') is not null then
    if exists (select 1 from pg_constraint where conname = 'battle_matches_course_key_ck') then
      alter table public.battle_matches drop constraint battle_matches_course_key_ck;
    end if;
    alter table public.battle_matches
      add constraint battle_matches_course_key_ck check (course_key in ('abu', 'automechaniker', 'fage', 'kv', 'schreiner', 'strassenbau'));
  end if;
end$$;

-- ============================================================
-- 2) KV: 1 Modul, 16 Lektionen je 30 Fragen
-- ============================================================
do $$
declare
  v_module_id uuid;
  v_lesson_id uuid;
begin
  select id into v_module_id from public.modules where course_key = 'kv' and title = 'Kauffrau/Kaufmann EFZ – Bildungsplan' limit 1;
  if v_module_id is null then
    insert into public.modules (title, description, course_key, position)
    values ('Kauffrau/Kaufmann EFZ – Bildungsplan', 'Bildungsplan Kauffrau/Kaufmann EFZ nach BiVo 2023 (SBFI/SKKAB). 16 Lektionen entlang der Handlungskompetenzbereiche HKB A–E mit Fokus auf Rolle/Betrieb, Interaktion mit Anspruchsgruppen, kaufmännische Arbeitsprozesse, Lernen/Arbeitstechniken sowie wirtschaftliche/gesellschaftliche Zusammenhänge.', 'kv', 100)
    returning id into v_module_id;
  else
    update public.modules set description = 'Bildungsplan Kauffrau/Kaufmann EFZ nach BiVo 2023 (SBFI/SKKAB). 16 Lektionen entlang der Handlungskompetenzbereiche HKB A–E mit Fokus auf Rolle/Betrieb, Interaktion mit Anspruchsgruppen, kaufmännische Arbeitsprozesse, Lernen/Arbeitstechniken sowie wirtschaftliche/gesellschaftliche Zusammenhänge.', position = 100 where id = v_module_id;
  end if;

  -- Lektion L01: L01 – Rolle, Betrieb und professionelle Entwicklung
  select id into v_lesson_id from public.lessons where module_id = v_module_id and title = 'L01 – Rolle, Betrieb und professionelle Entwicklung' limit 1;
  if v_lesson_id is null then
    insert into public.lessons (module_id, title, position, pass_score)
    values (v_module_id, 'L01 – Rolle, Betrieb und professionelle Entwicklung', 10, 70)
    returning id into v_lesson_id;
  else
    update public.lessons set position = 10, pass_score = 70 where id = v_lesson_id;
  end if;
  update public.questions set prompt = 'Welche Aussage beschreibt das Thema eigene Rolle im Betrieb im Beruf Kauffrau/Kaufmann EFZ am besten?', option_a = 'Aufgaben, Verantwortung und Erwartungen aktiv klären', option_b = 'nur private Interessen verfolgen im laufenden Tagesgeschäft', option_c = 'betriebliche Regeln ignorieren im konkreten Auftrag', option_d = 'Aufgaben ohne Rückfrage liegen lassen', correct_option = 'A', explanation = 'Kaufleute entwickeln ihre professionelle Rolle bewusst und betriebsgerecht.' where lesson_id = v_lesson_id and position = 1;
  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Welche Aussage beschreibt das Thema eigene Rolle im Betrieb im Beruf Kauffrau/Kaufmann EFZ am besten?', 'Aufgaben, Verantwortung und Erwartungen aktiv klären', 'nur private Interessen verfolgen im laufenden Tagesgeschäft', 'betriebliche Regeln ignorieren im konkreten Auftrag', 'Aufgaben ohne Rückfrage liegen lassen', 'A', 'Kaufleute entwickeln ihre professionelle Rolle bewusst und betriebsgerecht.', 1); end if;
  update public.questions set prompt = 'Worauf muss man beim Thema eigene Rolle im Betrieb in der Praxis besonders achten?', option_a = 'nur private Interessen verfolgen nach gängiger Praxis', option_b = 'Aufgaben, Verantwortung und Erwartungen aktiv klären', option_c = 'betriebliche Regeln ignorieren im üblichen Berufsalltag', option_d = 'Aufgaben ohne Rückfrage liegen lassen', correct_option = 'B', explanation = 'Kaufleute entwickeln ihre professionelle Rolle bewusst und betriebsgerecht.' where lesson_id = v_lesson_id and position = 2;
  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Worauf muss man beim Thema eigene Rolle im Betrieb in der Praxis besonders achten?', 'nur private Interessen verfolgen nach gängiger Praxis', 'Aufgaben, Verantwortung und Erwartungen aktiv klären', 'betriebliche Regeln ignorieren im üblichen Berufsalltag', 'Aufgaben ohne Rückfrage liegen lassen', 'B', 'Kaufleute entwickeln ihre professionelle Rolle bewusst und betriebsgerecht.', 2); end if;
  update public.questions set prompt = 'Welche Aussage zum Thema eigene Rolle im Betrieb ist fachlich korrekt?', option_a = 'nur private Interessen verfolgen im Produktionsalltag', option_b = 'betriebliche Regeln ignorieren im Werkstattumfeld', option_c = 'Aufgaben, Verantwortung und Erwartungen aktiv klären', option_d = 'Aufgaben ohne Rückfrage liegen lassen', correct_option = 'C', explanation = 'Kaufleute entwickeln ihre professionelle Rolle bewusst und betriebsgerecht.' where lesson_id = v_lesson_id and position = 3;
  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Welche Aussage zum Thema eigene Rolle im Betrieb ist fachlich korrekt?', 'nur private Interessen verfolgen im Produktionsalltag', 'betriebliche Regeln ignorieren im Werkstattumfeld', 'Aufgaben, Verantwortung und Erwartungen aktiv klären', 'Aufgaben ohne Rückfrage liegen lassen', 'C', 'Kaufleute entwickeln ihre professionelle Rolle bewusst und betriebsgerecht.', 3); end if;
