  if not found then insert into public.questions (lesson_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, position) values (v_lesson_id, 'Welche Aussage beschreibt das Thema Leitbild im Beruf Kauffrau/Kaufmann EFZ am besten?', 'nur als Dekoration behandeln unter typischen Arbeitsbedingungen', 'für Kundenkontakte ignorieren im Rahmen der Routine', 'durch persönliche Vorlieben ersetzen bei vergleichbaren Aufgaben', 'Werte und Grundsätze des Betriebs im Alltag berücksichtigen', 'D', 'Das Leitbild prägt Auftreten, Kommunikation und Entscheidungen.', 4); end if;
